// auth-security · кейс auth-20 (#834c8e) — .qa/tests/auth-security/
// API-тесты: пустой заказ нельзя создать прямым POST /rest/v1/orders (admin, buyer, rep) и через RPC с пустым списком.
// Ничего не создаётся. Если фикс сломан — появится неудаляемый пустой заказ «ממתינה לאישור» (отклонить, записать в «Тестовые данные для чистки»).
// UI-регресс (walk-in #698, «הזמנה מהודעה» #699/#700) не автоматизирован — создаёт неудаляемые заказы (см. skip в конце).
import { test, expect } from '../../fixtures';
import type { Page } from '@playwright/test';
import { openApp, sb, countRows } from './_supabase';

const ADMIN_ORDER_NO = 693; // существующий заказ admin/клиента «test» — источник distributor_id и customer_id

async function ids(admin: Page) {
  await openApp(admin);
  const r = await sb(admin, 'GET', `orders?select=distributor_id,customer_id&order_no=eq.${ADMIN_ORDER_NO}`);
  expect(r.status).toBe(200);
  expect(r.body.length, `заказ #${ADMIN_ORDER_NO} найден`).toBe(1);
  const prod = await sb(admin, 'GET', 'products?select=id&limit=1');
  return { distributor_id: r.body[0].distributor_id as string, customer_id: r.body[0].customer_id as string, productId: prod.body[0]?.id as string };
}

test.describe('auth-security — אי אפשר ליצור הזמנה ריקה / ישירות בטבלת orders (API)', () => {
  for (const role of ['admin', 'buyer', 'rep']) {
    test(`POST ישיר ל-/rest/v1/orders ללא פריטים תחת ${role} → 403 / 42501, מספר ההזמנות לא משתנה #834c8e @desktop @prod-safe`, async ({ asUser }) => {
      const admin = await asUser('admin');
      const f = await ids(admin);
      const who = role === 'admin' ? admin : await asUser(role);
      if (who !== admin) await openApp(who);
      const adminBefore = await countRows(admin, 'orders');
      const ownBefore = await countRows(who, 'orders');
      const r = await sb(who, 'POST', 'orders', { distributor_id: f.distributor_id, customer_id: f.customer_id, note: 'QA-AUTO-834c8e-direct' }, 'return=minimal');
      expect(r.status, 'HTTP').toBe(403);
      expect(r.body?.code, 'код').toBe('42501');
      expect(String(r.body?.message)).toContain('permission denied for table orders');
      expect(await countRows(who, 'orders'), `число заказов (${role}) не изменилось`).toBe(ownBefore);
      expect(await countRows(admin, 'orders'), 'число заказов admin не изменилось').toBe(adminBefore);
    });
  }

  test('place_order עם עגלה ריקה תחת buyer → 400 / 22023 / EMPTY_CART #834c8e @desktop @prod-safe', async ({ asUser }) => {
    const buyer = await asUser('buyer');
    await openApp(buyer);
    const before = await countRows(buyer, 'orders');
    const r = await sb(buyer, 'POST', 'rpc/place_order', { p_items: [] });
    expect(r.status, 'HTTP').toBe(400);
    expect(r.body?.code, 'код').toBe('22023');
    expect(String(r.body?.message)).toContain('EMPTY_CART');
    expect(await countRows(buyer, 'orders')).toBe(before);
  });

  test('create_customer_order ו-create_walkin_order עם p_items ריק תחת admin → 400 / 22023 / EMPTY_ORDER #834c8e @desktop @prod-safe', async ({ asUser }) => {
    const admin = await asUser('admin');
    const f = await ids(admin);
    const before = await countRows(admin, 'orders');
    const a = await sb(admin, 'POST', 'rpc/create_customer_order', { p_customer: f.customer_id, p_items: [] });
    const b = await sb(admin, 'POST', 'rpc/create_walkin_order', { p_customer_id: f.customer_id, p_items: [] });
    for (const [name, r] of [['create_customer_order', a], ['create_walkin_order', b]] as const) {
      expect(r.status, `${name}: HTTP`).toBe(400);
      expect(r.body?.code, `${name}: код`).toBe('22023');
      expect(String(r.body?.message), name).toContain('EMPTY_ORDER');
    }
    expect(await countRows(admin, 'orders')).toBe(before);
  });

  test('UI: מכירה מיידית והזמנה מהודעה עדיין יוצרות הזמנה עם פריטים (רגרסיה אחרי הסרת INSERT) #834c8e @desktop @data', async () => {
    test.skip(true, 'создаёт неудаляемые заказы (walk-in #698, «הזמנה מהודעה» #699/#700) — писать только по решению пользователя');
  });
});
